import itertools

# Define the number of pegs for each color
peg_counts = {'yellow': 5, 'red': 4, 'green': 3, 'blue': 2, 'orange': 1}

# Define the triangular peg board
board = []

# Fill the board with pegs
for i in range(5):
    board.append([''] * (5 - i))

# Place the pegs according to the given counts
for color, count in peg_counts.items():
    for _ in range(count):
        # Find the first available position for the current color
        for r in range(5):
            for c in range(5 - r):
                if board[r][c] == '':
                    board[r][c] = color
                    break
            if board[r][c] == '':
                break

# Check if the placement is valid
def is_valid_placement(board):
    for r in range(5):
        for c in range(5 - r):
            colors_in_row = set()
            colors_in_column = set()
            for dr in range(r, 5):
                for dc in range(c, 5 - (dr - r)):
                    if board[dr][dc] != '':
                        colors_in_row.add(board[dr][dc])
                    if r + dc - dr in board[dr][dc::-1]:
                        colors_in_column.add(board[dr][dc])
            if len(colors_in_row) > 1 or len(colors_in_column) > 1:
                return False
    return True

# Check the validity of the placed pegs
valid_placement = is_valid_placement(board)
if valid_placement:
    num_ways = 1 if valid_placement else 0
else:
    num_ways = 0

print(num_ways)
```
