pair A, B, C, D, E, F, H;

A = (2,5);
B = (0,0);
C = (8,0);
D = (A + reflect(B,C)*(A))/2;

draw(A--D);
draw((0,5)--(8,5));
draw((0,0)--(8,0));

dot("$(3,-10,1)$", A, N);
dot("$(-5 + 4t, -3 - 18t, 6 - 4t)$", D, S);
